-- ---------------------------------------------------------------------------------------------
-- CHECK constraints (Backend Schema 5.1-5.4)
-- ---------------------------------------------------------------------------------------------
ALTER TABLE public.voting_events
  ADD CONSTRAINT voting_events_name_length CHECK (char_length(btrim(name)) BETWEEN 2 AND 150),
  ADD CONSTRAINT voting_events_window CHECK (end_at > start_at),
  -- PRD 4.3: an Open event cannot be deactivated.
  ADD CONSTRAINT voting_events_open_is_active CHECK (status <> 'open' OR is_active),
  ADD CONSTRAINT voting_events_cancel_reason CHECK (status <> 'cancelled' OR cancel_reason IS NOT NULL),
  ADD CONSTRAINT voting_events_reminders_positive CHECK (
    (reminder_before_open_hours IS NULL OR reminder_before_open_hours > 0)
    AND (reminder_before_close_minutes IS NULL OR reminder_before_close_minutes > 0)),
  ADD CONSTRAINT voting_events_results_token_format
    CHECK (public_results_token IS NULL OR public_results_token ~ '^[A-Za-z0-9_-]{32}$'),
  ADD CONSTRAINT voting_events_reopen_count CHECK (reopen_count >= 0),
  -- Soft delete: Draft or Cancelled only.
  ADD CONSTRAINT voting_events_delete_status
    CHECK (deleted_at IS NULL OR status IN ('draft', 'cancelled'));

ALTER TABLE public.categories
  ADD CONSTRAINT categories_name_length CHECK (char_length(btrim(name)) BETWEEN 1 AND 100),
  ADD CONSTRAINT categories_display_order CHECK (display_order >= 0),
  ADD CONSTRAINT categories_window CHECK (closes_at IS NULL OR opens_at IS NULL OR closes_at > opens_at),
  ADD CONSTRAINT categories_selection CHECK (
    (selection_mode = 'exact' AND exact_count >= 1)
    OR (selection_mode = 'range' AND min_count >= 1 AND max_count >= min_count)),
  ADD CONSTRAINT categories_seats CHECK (seats >= 1),
  ADD CONSTRAINT categories_threshold CHECK (
    (winner_rule <> 'threshold' OR threshold_pct IS NOT NULL)
    AND (threshold_pct IS NULL OR (threshold_pct > 0 AND threshold_pct <= 100))),
  ADD CONSTRAINT categories_quorum CHECK (quorum_pct IS NULL OR (quorum_pct > 0 AND quorum_pct <= 100));

ALTER TABLE public.contesters
  ADD CONSTRAINT contesters_name_length CHECK (char_length(btrim(full_name)) BETWEEN 1 AND 120),
  ADD CONSTRAINT contesters_ussd_name_length
    CHECK (ussd_short_name IS NULL OR char_length(ussd_short_name) <= 20),
  ADD CONSTRAINT contesters_withdrawn CHECK ((status = 'withdrawn') = (withdrawn_at IS NOT NULL));

ALTER TABLE public.voters
  ADD CONSTRAINT voters_name_length CHECK (char_length(btrim(full_name)) BETWEEN 1 AND 150),
  ADD CONSTRAINT voters_membership_id CHECK (membership_id_normalized <> ''),
  ADD CONSTRAINT voters_phone_e164 CHECK (phone ~ '^\+[1-9][0-9]{7,14}$'),
  ADD CONSTRAINT voters_failed_attempts CHECK (failed_attempts >= 0),
  ADD CONSTRAINT voters_code_pair CHECK ((code_hmac IS NULL) = (code_ciphertext IS NULL));

