-- ---------------------------------------------------------------------------------------------
-- 11.2 app.guard_event_update(): outside Draft only these event columns may change; status,
-- the lifecycle timestamps, cancel_reason and reopen_count change only inside
-- app.transition_event() (current_user = 'vk_owner'). SECURITY INVOKER on purpose: inside the
-- SECURITY DEFINER transition function current_user is vk_owner, for the API it is vk_api.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app.guard_event_update() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public
AS $$
DECLARE
  lifecycle text[] := ARRAY['status', 'opened_at', 'closed_at', 'results_published_at',
                            'cancelled_at', 'archived_at', 'cancel_reason', 'reopen_count'];
  allowed text[] := ARRAY['is_active', 'public_results_enabled', 'public_results_token',
                          'first_code_sent_at', 'reminder_before_open_hours',
                          'reminder_before_close_minutes', 'results_visibility', 'updated_at'];
  old_row jsonb := to_jsonb(OLD);
  new_row jsonb := to_jsonb(NEW);
  key text;
BEGIN
  IF current_user = 'vk_owner' THEN
    RETURN NEW;
  END IF;
  FOREACH key IN ARRAY lifecycle LOOP
    IF new_row -> key IS DISTINCT FROM old_row -> key THEN
      RAISE EXCEPTION 'INVALID_TRANSITION' USING ERRCODE = 'P0001';
    END IF;
  END LOOP;
  IF OLD.status = 'draft' THEN
    RETURN NEW;
  END IF;
  IF OLD.status = 'cancelled' THEN
    allowed := allowed || 'deleted_at';
  END IF;
  IF (new_row - allowed) IS DISTINCT FROM (old_row - allowed) THEN
    RAISE EXCEPTION 'EVENT_LOCKED' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER voting_events_guard BEFORE UPDATE ON public.voting_events
  FOR EACH ROW EXECUTE FUNCTION app.guard_event_update();

-- ---------------------------------------------------------------------------------------------
-- 11.2 app.guard_event_setup(): the setup of a published event is locked. In Draft anything
-- goes; otherwise only the columns in the 11.2 table may change and nothing may be added or
-- removed. SECURITY INVOKER for the same reason as above; vk_owner (transition_event, the
-- result freeze, tests seeding as owner) is not restricted.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app.guard_event_setup() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public
AS $$
DECLARE
  v_event uuid;
  v_status event_status;
  allowed text[];
BEGIN
  IF current_user = 'vk_owner' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_TABLE_NAME = 'category_voters' THEN
    SELECT c.event_id INTO v_event FROM public.categories c
    WHERE c.id = COALESCE(NEW.category_id, OLD.category_id);
    -- A voter is eligible only for categories of their own event.
    IF TG_OP <> 'DELETE' AND NOT EXISTS (
      SELECT 1 FROM public.voters v WHERE v.id = NEW.voter_id AND v.event_id = v_event) THEN
      RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE = 'P0001';
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    v_event := OLD.event_id;
  ELSE
    v_event := NEW.event_id;
    IF TG_OP = 'UPDATE' AND NEW.event_id IS DISTINCT FROM OLD.event_id THEN
      RAISE EXCEPTION 'EVENT_LOCKED' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  SELECT e.status INTO v_status FROM public.voting_events e WHERE e.id = v_event;
  IF v_status IS NULL OR v_status = 'draft' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  IF TG_OP <> 'UPDATE' THEN
    RAISE EXCEPTION 'EVENT_LOCKED' USING ERRCODE = 'P0001';
  END IF;

  allowed := CASE TG_TABLE_NAME
    WHEN 'categories' THEN
      CASE WHEN v_status = 'open' THEN ARRAY['manual_state', 'closed_at', 'is_active'] ELSE ARRAY[]::text[] END
    WHEN 'contesters' THEN
      CASE WHEN v_status = 'scheduled' THEN ARRAY['status', 'withdrawn_at'] ELSE ARRAY[]::text[] END
    WHEN 'voters' THEN
      ARRAY['code_hmac', 'code_ciphertext', 'code_status', 'code_generated_at', 'code_last_sent_at',
            'failed_attempts', 'locked_until']
    ELSE ARRAY[]::text[]
  END || ARRAY['updated_at'];

  IF (to_jsonb(NEW) - allowed) IS DISTINCT FROM (to_jsonb(OLD) - allowed) THEN
    RAISE EXCEPTION 'EVENT_LOCKED' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER categories_guard_setup BEFORE INSERT OR UPDATE OR DELETE ON public.categories
  FOR EACH ROW EXECUTE FUNCTION app.guard_event_setup();
CREATE TRIGGER contesters_guard_setup BEFORE INSERT OR UPDATE OR DELETE ON public.contesters
  FOR EACH ROW EXECUTE FUNCTION app.guard_event_setup();
CREATE TRIGGER category_voters_guard_setup BEFORE INSERT OR UPDATE OR DELETE ON public.category_voters
  FOR EACH ROW EXECUTE FUNCTION app.guard_event_setup();
CREATE TRIGGER voters_guard_setup BEFORE INSERT OR UPDATE OR DELETE ON public.voters
  FOR EACH ROW EXECUTE FUNCTION app.guard_event_setup();

-- ---------------------------------------------------------------------------------------------
-- 11.2 app.check_category_window(): a category's own times lie inside its event's window.
-- The event side (app.check_event_window) keeps that true when the event window changes.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app.check_category_window() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public
AS $$
DECLARE
  v_start timestamptz;
  v_end timestamptz;
BEGIN
  SELECT e.start_at, e.end_at INTO v_start, v_end FROM public.voting_events e WHERE e.id = NEW.event_id;
  IF (NEW.opens_at IS NOT NULL AND (NEW.opens_at < v_start OR NEW.opens_at >= v_end))
     OR (NEW.closes_at IS NOT NULL AND (NEW.closes_at <= v_start OR NEW.closes_at > v_end)) THEN
    RAISE EXCEPTION 'CATEGORY_WINDOW_INVALID' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER categories_window BEFORE INSERT OR UPDATE OF opens_at, closes_at, event_id
  ON public.categories FOR EACH ROW EXECUTE FUNCTION app.check_category_window();

CREATE FUNCTION app.check_event_window() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, public
AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.categories c
    WHERE c.event_id = NEW.id
      AND ((c.opens_at IS NOT NULL AND (c.opens_at < NEW.start_at OR c.opens_at >= NEW.end_at))
           OR (c.closes_at IS NOT NULL AND (c.closes_at <= NEW.start_at OR c.closes_at > NEW.end_at)))) THEN
    RAISE EXCEPTION 'CATEGORY_WINDOW_INVALID' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER voting_events_window BEFORE UPDATE OF start_at, end_at ON public.voting_events
  FOR EACH ROW EXECUTE FUNCTION app.check_event_window();

-- ---------------------------------------------------------------------------------------------
-- 5.2 app.category_is_votable(): the one definition of "votable now", used by the ballot
-- function and the API. Also false once the event's end time has passed (hard close, PRD 4.3
-- rule 4), even before the scheduler moves the event to Closed.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app.category_is_votable(p_category_id uuid) RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path = pg_catalog, public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.categories c
    JOIN public.voting_events e ON e.id = c.event_id
    WHERE c.id = p_category_id
      AND e.status = 'open'
      AND e.deleted_at IS NULL
      AND now() < e.end_at
      AND c.is_active
      AND c.closed_at IS NULL
      AND (c.manual_state = 'open'
           OR (c.manual_state = 'auto'
               AND (c.opens_at IS NULL OR c.opens_at <= now())
               AND (c.closes_at IS NULL OR now() < c.closes_at))))
$$;

-- 5.5 app.voter_is_eligible(): eligibility 'all', or a category_voters row.
CREATE FUNCTION app.voter_is_eligible(p_voter_id uuid, p_category_id uuid) RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path = pg_catalog, public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.voters v
    JOIN public.categories c ON c.event_id = v.event_id
    WHERE v.id = p_voter_id
      AND c.id = p_category_id
      AND v.deleted_at IS NULL
      AND (c.eligibility = 'all'
           OR EXISTS (SELECT 1 FROM public.category_voters cv
                      WHERE cv.category_id = c.id AND cv.voter_id = v.id)))
$$;

-- ---------------------------------------------------------------------------------------------
-- 11.5 app.publish_checklist(): the six checks of App Flow 6.3, in order, with details naming
-- what to fix. SECURITY INVOKER: RLS limits it to the caller's organization.
--   details      event details complete (name, start and end, end after start)
--   categories   at least one active category
--   contesters   every active category has an active contester
--   rules        every active category's rules fit its contesters (one contester = Yes/No)
--   voters       voters added
--   eligibility  every active category has eligible voters
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app.publish_checklist(p_event_id uuid)
RETURNS TABLE (item text, ok boolean, detail jsonb)
  LANGUAGE sql
  STABLE
  SET search_path = pg_catalog, public
AS $$
  WITH ev AS (
    SELECT e.* FROM public.voting_events e WHERE e.id = p_event_id AND e.deleted_at IS NULL
  ),
  cats AS (
    SELECT c.id, c.selection_mode, c.exact_count, c.min_count, c.max_count, c.seats, c.eligibility,
           (SELECT count(*) FROM public.contesters k
            WHERE k.category_id = c.id AND k.status = 'active') AS contesters,
           (SELECT count(*) FROM public.category_voters cv
            JOIN public.voters v ON v.id = cv.voter_id AND v.deleted_at IS NULL
            WHERE cv.category_id = c.id) AS selected_voters
    FROM public.categories c
    WHERE c.event_id = p_event_id AND c.is_active
  ),
  voter_count AS (
    SELECT count(*) AS n FROM public.voters v WHERE v.event_id = p_event_id AND v.deleted_at IS NULL
  ),
  bad_rules AS (
    SELECT id FROM cats
    WHERE contesters > 1
      AND NOT (seats <= contesters
               AND ((selection_mode = 'exact' AND exact_count <= contesters)
                    OR (selection_mode = 'range' AND max_count <= contesters)))
  ),
  no_contesters AS (SELECT id FROM cats WHERE contesters = 0),
  no_voters AS (
    SELECT id FROM cats
    WHERE (eligibility = 'all' AND (SELECT n FROM voter_count) = 0)
       OR (eligibility = 'selected' AND selected_voters = 0)
  )
  SELECT item, ok, detail FROM (
    SELECT 1 AS ord, 'details'::text AS item,
           EXISTS (SELECT 1 FROM ev WHERE char_length(btrim(name)) >= 2 AND end_at > start_at) AS ok,
           '{}'::jsonb AS detail
    UNION ALL
    SELECT 2, 'categories', EXISTS (SELECT 1 FROM cats),
           jsonb_build_object('activeCategories', (SELECT count(*) FROM cats))
    UNION ALL
    SELECT 3, 'contesters', EXISTS (SELECT 1 FROM cats) AND NOT EXISTS (SELECT 1 FROM no_contesters),
           jsonb_build_object('categoryIds', COALESCE((SELECT jsonb_agg(id) FROM no_contesters), '[]'::jsonb))
    UNION ALL
    SELECT 4, 'rules', EXISTS (SELECT 1 FROM cats) AND NOT EXISTS (SELECT 1 FROM bad_rules),
           jsonb_build_object('categoryIds', COALESCE((SELECT jsonb_agg(id) FROM bad_rules), '[]'::jsonb))
    UNION ALL
    SELECT 5, 'voters', (SELECT n FROM voter_count) > 0,
           jsonb_build_object('voters', (SELECT n FROM voter_count))
    UNION ALL
    SELECT 6, 'eligibility', EXISTS (SELECT 1 FROM cats) AND NOT EXISTS (SELECT 1 FROM no_voters),
           jsonb_build_object('categoryIds', COALESCE((SELECT jsonb_agg(id) FROM no_voters), '[]'::jsonb))
  ) checks
  ORDER BY ord
$$;

-- ---------------------------------------------------------------------------------------------
-- 11.5 app.transition_event(): the only way to change an event's status. Locks the row, checks
-- the move, applies its side effects and returns the updated row; the API writes the audit entry
-- in the same transaction. Close, reopen and results publication arrive with results (step 27).
-- SECURITY DEFINER: it alone may write the lifecycle columns (guard_event_update), so it checks
-- the caller's organization itself.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app.transition_event(
  p_event_id uuid,
  p_to event_status,
  p_reason text DEFAULT NULL,
  p_new_end_at timestamptz DEFAULT NULL,
  p_results_token text DEFAULT NULL
) RETURNS public.voting_events
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = pg_catalog, public
AS $$
DECLARE
  e public.voting_events;
BEGIN
  SELECT * INTO e FROM public.voting_events
  WHERE id = p_event_id AND deleted_at IS NULL
  FOR UPDATE;
  IF NOT FOUND OR e.organization_id IS DISTINCT FROM app.current_org_id() THEN
    RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  -- PRD 4.3: a deactivated event cannot change status.
  IF NOT e.is_active THEN
    RAISE EXCEPTION 'INVALID_TRANSITION' USING ERRCODE = 'P0001';
  END IF;

  IF e.status = 'draft' AND p_to = 'scheduled' THEN
    IF EXISTS (SELECT 1 FROM app.publish_checklist(p_event_id) WHERE NOT ok) THEN
      RAISE EXCEPTION 'CHECKLIST_FAILED' USING ERRCODE = 'P0001';
    END IF;
    IF e.start_at <= now() THEN
      RAISE EXCEPTION 'INVALID_TRANSITION' USING ERRCODE = 'P0001';
    END IF;
    UPDATE public.voting_events SET status = 'scheduled' WHERE id = p_event_id RETURNING * INTO e;

  ELSIF e.status IN ('draft', 'scheduled') AND p_to = 'open' THEN
    IF e.status = 'draft' AND EXISTS (SELECT 1 FROM app.publish_checklist(p_event_id) WHERE NOT ok) THEN
      RAISE EXCEPTION 'CHECKLIST_FAILED' USING ERRCODE = 'P0001';
    END IF;
    -- Opening after the end time would accept no vote at all.
    IF e.end_at <= now() THEN
      RAISE EXCEPTION 'INVALID_TRANSITION' USING ERRCODE = 'P0001';
    END IF;
    UPDATE public.voting_events SET status = 'open', opened_at = now()
    WHERE id = p_event_id RETURNING * INTO e;

  ELSIF e.status = 'scheduled' AND p_to = 'draft' THEN
    IF e.first_code_sent_at IS NOT NULL THEN
      RAISE EXCEPTION 'INVALID_TRANSITION' USING ERRCODE = 'P0001';
    END IF;
    UPDATE public.voting_events SET status = 'draft' WHERE id = p_event_id RETURNING * INTO e;

  ELSIF e.status IN ('draft', 'scheduled', 'open') AND p_to = 'cancelled' THEN
    IF p_reason IS NULL OR char_length(btrim(p_reason)) < 10 THEN
      RAISE EXCEPTION 'VALIDATION_FAILED' USING ERRCODE = 'P0001';
    END IF;
    UPDATE public.voting_events SET status = 'cancelled', cancelled_at = now(), cancel_reason = btrim(p_reason)
    WHERE id = p_event_id RETURNING * INTO e;

  ELSIF e.status IN ('results_published', 'cancelled') AND p_to = 'archived' THEN
    UPDATE public.voting_events SET status = 'archived', archived_at = now()
    WHERE id = p_event_id RETURNING * INTO e;

  ELSE
    RAISE EXCEPTION 'INVALID_TRANSITION' USING ERRCODE = 'P0001';
  END IF;

  RETURN e;
END $$;

REVOKE ALL ON FUNCTION app.transition_event(uuid, event_status, text, timestamptz, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.transition_event(uuid, event_status, text, timestamptz, text) TO vk_api;
GRANT EXECUTE ON FUNCTION app.publish_checklist(uuid), app.category_is_votable(uuid),
  app.voter_is_eligible(uuid, uuid) TO vk_api, vk_readonly;

-- ---------------------------------------------------------------------------------------------
-- Row level security (Backend Schema 10.2). Platform administrators read events, assignments,
-- categories, contesters and category links, never individual voters.
-- ---------------------------------------------------------------------------------------------
ALTER TABLE public.voting_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY voting_events_tenant ON public.voting_events FOR ALL TO vk_api
  USING (organization_id = app.current_org_id())
  WITH CHECK (organization_id = app.current_org_id());
CREATE POLICY voting_events_platform_read ON public.voting_events FOR SELECT TO vk_api
  USING (app.is_platform_admin());

ALTER TABLE public.event_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_assignments_tenant ON public.event_assignments FOR ALL TO vk_api
  USING (organization_id = app.current_org_id())
  WITH CHECK (organization_id = app.current_org_id());
CREATE POLICY event_assignments_platform_read ON public.event_assignments FOR SELECT TO vk_api
  USING (app.is_platform_admin());

ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY categories_tenant ON public.categories FOR ALL TO vk_api
  USING (organization_id = app.current_org_id())
  WITH CHECK (organization_id = app.current_org_id());
CREATE POLICY categories_platform_read ON public.categories FOR SELECT TO vk_api
  USING (app.is_platform_admin());

ALTER TABLE public.contesters ENABLE ROW LEVEL SECURITY;
CREATE POLICY contesters_tenant ON public.contesters FOR ALL TO vk_api
  USING (organization_id = app.current_org_id())
  WITH CHECK (organization_id = app.current_org_id());
CREATE POLICY contesters_platform_read ON public.contesters FOR SELECT TO vk_api
  USING (app.is_platform_admin());

ALTER TABLE public.voters ENABLE ROW LEVEL SECURITY;
CREATE POLICY voters_tenant ON public.voters FOR ALL TO vk_api
  USING (organization_id = app.current_org_id())
  WITH CHECK (organization_id = app.current_org_id());

ALTER TABLE public.category_voters ENABLE ROW LEVEL SECURITY;
CREATE POLICY category_voters_tenant ON public.category_voters FOR ALL TO vk_api
  USING (organization_id = app.current_org_id())
  WITH CHECK (organization_id = app.current_org_id());
CREATE POLICY category_voters_platform_read ON public.category_voters FOR SELECT TO vk_api
  USING (app.is_platform_admin());

-- ---------------------------------------------------------------------------------------------
-- Grants (Backend Schema 10.4). The support role never sees code fingerprints or ciphertexts.
-- ---------------------------------------------------------------------------------------------
GRANT SELECT, INSERT, UPDATE, DELETE ON public.voting_events, public.event_assignments,
  public.categories, public.contesters, public.voters, public.category_voters TO vk_api;

REVOKE ALL ON public.voters FROM vk_readonly;
GRANT SELECT ON public.voting_events, public.event_assignments, public.categories,
  public.contesters, public.category_voters TO vk_readonly;
GRANT SELECT (id, organization_id, event_id, full_name, membership_id, membership_id_normalized,
              phone, email, gender, photo_file_id, code_status, code_generated_at,
              code_last_sent_at, failed_attempts, locked_until, created_at, updated_at, deleted_at)
  ON public.voters TO vk_readonly;
